"use client";

import Link from "next/link";
import { useState, useRef, useEffect } from "react";
import { Menu, ShoppingCart, User, X, Sprout, Bell } from "lucide-react";
import { usePathname } from "next/navigation";
import clsx from "clsx";
import CartBadge from "./CartBadge";
import { NotificationService } from "@/services/notification.service";
import SearchInput from "@/components/common/SearchInput";

import { useAuth } from "@/context/AuthContext";

export default function Navbar() {
    const [isOpen, setIsOpen] = useState(false);
    const [isProfileOpen, setIsProfileOpen] = useState(false);
    const profileRef = useRef<HTMLDivElement>(null);
    const pathname = usePathname();
    const { user, dbUser, logout } = useAuth();
    const [unreadCount, setUnreadCount] = useState(0);

    const links = [
        { href: "/", label: "Home" },
        { href: "/shop", label: "Shop" },
        { href: "/about", label: "Our Story" },
        { href: "/blog", label: "Blog" },
        { href: "/contact", label: "Contact Us" },
    ];

    const isActive = (path: string) => pathname === path;

    useEffect(() => {
        function handleClickOutside(event: MouseEvent | TouchEvent) {
            if (profileRef.current && !profileRef.current.contains(event.target as Node)) {
                setIsProfileOpen(false);
            }
        }
        document.addEventListener("mousedown", handleClickOutside);
        document.addEventListener("touchstart", handleClickOutside);

        let unsubscribe: (() => void) | undefined;
        if (user) {
            unsubscribe = NotificationService.subscribeToUnreadCount(user.uid, (count) => {
                setUnreadCount(count);
            });
        }

        return () => {
            document.removeEventListener("mousedown", handleClickOutside);
            document.removeEventListener("touchstart", handleClickOutside);
            if (unsubscribe) unsubscribe();
        };
    }, [user]);

    return (
        <nav className="bg-white/80 backdrop-blur-md border-b border-gray-100 sticky top-0 z-50">
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                <div className="flex justify-between h-20 items-center">
                    {/* Logo */}
                    <Link href="/" className="flex items-center shrink-0">
                        <img
                            src="/images/logo.png"
                            alt="Greenbird Homestead"
                            className="h-10 sm:h-12 md:h-16 w-auto object-contain"
                        />
                    </Link>

                    {/* Search Field - Visible on all screens */}
                    <div className="flex-1 max-w-xl mx-2 md:mx-4">
                        <SearchInput />
                    </div>

                    {/* Desktop Links - Hidden on small screens, shown on large */}
                    <div className="hidden lg:flex space-x-6">
                        {links.map((link) => (
                            <Link
                                key={link.href}
                                href={link.href}
                                className={clsx(
                                    "text-sm font-medium transition-colors duration-200 whitespace-nowrap",
                                    isActive(link.href)
                                        ? "text-[#2D5A27]"
                                        : "text-gray-600 hover:text-[#2D5A27]"
                                )}
                            >
                                {link.label}
                            </Link>
                        ))}
                    </div>

                    {/* Right Icons */}
                    <div className="flex items-center space-x-4">
                        {user && (
                            <div className="flex items-center space-x-2">
                                <Link href="/notifications" className="relative p-2 text-gray-600 hover:bg-gray-100 rounded-full transition-colors">
                                    <Bell className="h-5 w-5" />
                                    {unreadCount > 0 && (
                                        <span className="absolute top-0 right-0 h-4 w-4 bg-red-500 text-white text-[10px] font-bold flex items-center justify-center rounded-full animate-pulse">
                                            {unreadCount > 9 ? '9+' : unreadCount}
                                        </span>
                                    )}
                                </Link>
                                <Link href="/cart" className="relative p-2 text-gray-600 hover:bg-gray-100 rounded-full transition-colors">
                                    <ShoppingCart className="h-5 w-5" />
                                    <CartBadge />
                                </Link>
                            </div>
                        )}

                        {user ? (
                            <div className="relative" ref={profileRef}>
                                <button
                                    onClick={() => setIsProfileOpen(!isProfileOpen)}
                                    className="flex items-center space-x-2 p-2 text-gray-700 hover:bg-gray-50 rounded-lg transition-colors"
                                >
                                    <div className="h-8 w-8 bg-green-100 rounded-full flex items-center justify-center text-green-700 font-bold overflow-hidden">
                                        {user.photoURL ? (
                                            <img src={user.photoURL} alt={user.displayName || "User"} className="h-full w-full object-cover" />
                                        ) : (
                                            (user.displayName || "U").charAt(0).toUpperCase()
                                        )}
                                    </div>
                                    <span className="hidden lg:block font-medium text-sm">
                                        Hi, {user.displayName?.split(" ")[0] || "User"}
                                    </span>
                                </button>

                                {/* Dropdown Menu */}
                                {isProfileOpen && (
                                    <div className="absolute right-0 mt-2 w-48 bg-white rounded-xl shadow-lg border border-gray-100 py-1 transition-all transform origin-top-right z-50">
                                        <div className="px-4 py-3 border-b border-gray-50 md:hidden">
                                            <p className="text-sm font-bold text-gray-900">{user.displayName || "User"}</p>
                                            <p className="text-xs text-gray-500 truncate">{user.email}</p>
                                        </div>

                                        <Link
                                            href="/profile"
                                            className="block px-4 py-2 text-sm text-gray-700 hover:bg-green-50 hover:text-green-700"
                                            onClick={() => setIsProfileOpen(false)}
                                        >
                                            My Profile
                                        </Link>
                                        {dbUser?.role !== 'admin' && (
                                            <Link
                                                href="/orders"
                                                className="block px-4 py-2 text-sm text-gray-700 hover:bg-green-50 hover:text-green-700"
                                                onClick={() => setIsProfileOpen(false)}
                                            >
                                                My Orders
                                            </Link>
                                        )}
                                        {(dbUser?.role === 'admin' || dbUser?.role === 'manager') && (
                                            <Link
                                                href="/admin"
                                                className="block px-4 py-2 text-sm text-gray-700 hover:bg-green-50 hover:text-green-700"
                                                onClick={() => setIsProfileOpen(false)}
                                            >
                                                Admin Dashboard
                                            </Link>
                                        )}
                                        <button
                                            onClick={() => {
                                                setIsProfileOpen(false);
                                                logout();
                                            }}
                                            className="block w-full text-left px-4 py-2 text-sm text-red-600 hover:bg-red-50"
                                        >
                                            Logout
                                        </button>
                                    </div>
                                )}
                            </div>
                        ) : (
                            <Link href="/login" className="flex items-center space-x-1 px-3 py-1.5 sm:px-4 sm:py-2 bg-green-600 text-white rounded-lg text-xs sm:text-sm font-bold hover:bg-green-700 transition-colors shrink-0">
                                <User className="h-3 w-3 sm:h-4 sm:h-4" />
                                <span>Login</span>
                            </Link>
                        )}

                        {/* Mobile Menu Button */}
                        <button
                            onClick={() => setIsOpen(!isOpen)}
                            className="md:hidden p-2 text-gray-600 hover:bg-gray-100 rounded-lg"
                        >
                            {isOpen ? <X className="h-6 w-6" /> : <Menu className="h-6 w-6" />}
                        </button>
                    </div>
                </div>
            </div>

            {/* Mobile Menu */}
            {isOpen && (
                <div className="md:hidden border-t border-gray-100 bg-white">
                    <div className="px-2 pt-2 pb-3 space-y-1 sm:px-3">
                        {(dbUser?.role === 'admin' || dbUser?.role === 'manager') && (
                            <Link
                                href="/admin"
                                onClick={() => setIsOpen(false)}
                                className={clsx(
                                    "block px-3 py-2 rounded-md text-base font-medium transition-colors text-green-600 hover:bg-green-50"
                                )}
                            >
                                Admin Dashboard
                            </Link>
                        )}
                        {links.map((link) => (
                            <Link
                                key={link.href}
                                href={link.href}
                                onClick={() => setIsOpen(false)}
                                className={clsx(
                                    "block px-3 py-2 rounded-md text-base font-medium transition-colors",
                                    isActive(link.href)
                                        ? "bg-[#2D5A27]/10 text-[#2D5A27]"
                                        : "text-gray-700 hover:bg-gray-50 hover:text-[#2D5A27]"
                                )}
                            >
                                {link.label}
                            </Link>
                        ))}
                    </div>
                </div>
            )}
        </nav>
    );
}
